(()=>{'use strict';const {defaults,clone,validate,targetIndex}=LuckModel;let config=clone(defaults),device=null,screen='start',winner=2,index=0,frame=0,spinning=false,startTime=0,startIndex=0,endIndex=0,previous=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let mode=()=>device||(innerWidth<=600?'mobile':'desktop');const tell=(type,extra={})=>{if(parent!==window)parent.postMessage({source:'luck-preview',type,...extra},location.origin);};
function card(p,i){let d=config[mode()];return `<li class="prize ${p.image?'has-image':''}" data-prize="${i}" style="background-color:${p.color||config.theme.card};${d.cardBackground?`background-image:url('${d.cardBackground}')`:''}">${p.image?`<img src="${p.image}" alt="${esc(p.title)}">`:`<span class="value">${esc(p.value)}</span>`}${config.settings.showPrizeText?`<span class="prize-title">${esc(p.title)}</span>`:''}</li>`;}
function arrows(){let img=config[mode()].arrowImage;return ['',' end'].map(x=>img?`<img class="arrow${x}" src="${img}" alt="">`:`<svg class="arrow${x}" viewBox="0 0 30 30" aria-hidden="true"><path d="M3 2L28 15L3 28L7 15Z" fill="currentColor"/></svg>`).join('');}
function content(){const c=config.copy,p=config.prizes[winner]||config.prizes[0];if(screen==='start')return `<p class="eyebrow">${esc(c.eyebrow)}</p><h1 tabindex="-1">${esc(c.title)}</h1><p class="description">${esc(c.description)}</p><form id="spin-form">${config.settings.form?`<div class="test-form"><label>Тестовый email<input type="email" placeholder="design@example.com" required autocomplete="off"></label><label class="consent"><input type="checkbox" required> Я понимаю, что это тест и данные никуда не отправляются.</label></div>`:''}<button class="primary" id="spin" type="submit">${esc(c.button)} <span aria-hidden="true">↗</span></button></form><p class="spin-status" role="status" id="spin-status">${spinning?'Лента вращается…':'Каждый запуск — новый тест'}</p>`;if(screen==='win')return `<p class="eyebrow">ВАШ ВЫИГРЫШ</p><h1 tabindex="-1">${esc(c.winTitle)}</h1><div class="winning-label">${esc(p.title)}</div><p class="description">${esc(c.winDescription)}</p><button class="primary" id="claim">${esc(c.claim)} ↗</button><p class="microcopy">Демонстрационный результат</p>`;return `${config.assets.success?`<img class="success-art" src="${config.assets.success}" alt="Подарок">`:'<div class="success-symbol" aria-hidden="true">✓</div>'}<h1 tabindex="-1">${esc(c.successTitle)}</h1><p class="description">${esc(c.successDescription)}</p><div class="winning-label">${esc(p.title)}</div><div class="code"><strong id="promo">${esc(p.code)}</strong><button id="copy">Копировать</button></div><button class="secondary" id="again">${esc(c.restart)}</button><p class="microcopy" id="copy-status" role="status">Промокод не действует в магазине</p>`;}
function render(reset=true){clearTimeout(completionTimer);cancelAnimationFrame(frame);spinning=false;const m=mode(),d=config[m],t=config.theme;document.documentElement.style.cssText='';for(const [k,v]of Object.entries(t))document.documentElement.style.setProperty('--'+k,v);for(const k of ['titleSize','bodySize','cardSize','gap','radius','padding','arrowSize'])document.documentElement.style.setProperty('--'+k,d[k]+'px');document.documentElement.style.setProperty('--weight',t.weight);document.documentElement.style.setProperty('--imageScale',config.settings.imageScale+'%');document.documentElement.style.setProperty('--imageFit',config.settings.imageFit);
const vertical=['left','right'].includes(d.position);document.body.className=(m==='mobile'?'is-mobile ':'')+'position-'+d.position;$('#app').innerHTML=`<section class="scene ${d.background?'has-background':''}" style="${d.background?`background-image:url('${d.background}');background-size:${config.settings.backgroundFit}`:''}">${d.decoration?`<img class="decoration" src="${d.decoration}" alt="">`:''}<header class="scene-header">${config.assets.logo?`<img class="logo" src="${config.assets.logo}" alt="${esc(config.copy.brand)}">`:`<span class="wordmark">${esc(config.copy.brand)}</span>`}<span class="demo-badge">DESIGN PREVIEW</span></header><div class="layout"><div class="content">${content()}</div><div class="tape ${vertical?'vertical':''}" aria-label="Призовая лента">${arrows()}<div class="tape-mask"><ul class="tape-list" aria-hidden="true">${Array.from({length:14},()=>config.prizes.map(card).join('')).join('')}</ul></div></div><footer class="scene-footer"><span>Тестовая механика · без интеграции с Mindbox</span><span>Подарки, которые радуют ↗</span></footer></section>`;
if(reset)index=config.prizes.length*2+(screen==='start'?0:winner);previous=0;paint();bind();frame=requestAnimationFrame(tick);tell('screen',{screen});}
function paint(){const list=$('.tape-list'),mask=$('.tape-mask');if(!list||!mask)return;const d=config[mode()],vertical=['left','right'].includes(d.position),size=vertical?mask.clientHeight:mask.clientWidth;const offset=size/2-d.cardSize/2-index*(d.cardSize+d.gap);list.style.transform=vertical?`translate3d(0,${offset}px,0)`:`translate3d(${offset}px,0,0)`;}
function tick(now){const dt=previous?Math.min((now-previous)/1000,.05):0;previous=now;if(spinning){const duration=(reduced?.12:config.settings.duration)*1000;const progress=Math.min((now-startTime)/duration,1);index=startIndex+(endIndex-startIndex)*(1-Math.pow(1-progress,4));paint();if(progress>=1){spinning=false;index=endIndex;paint();document.querySelectorAll('.prize').forEach(el=>el.classList.toggle('selected',+el.dataset.prize===winner));$('#spin-status').textContent='Ваш приз: '+config.prizes[winner].title;completionTimer=setTimeout(()=>{if(screen==='start'&&!spinning){screen=config.settings.secondScreen?'win':'success';render();$('.content h1')?.focus({preventScroll:true});}},650);return;}}else if(screen==='start'&&config.settings.idle&&!reduced){index+=dt*.27;const n=config.prizes.length;if(index>n*3)index-=n;paint();}frame=requestAnimationFrame(tick);}
let completionTimer;function spin(){if(spinning)return;winner=config.settings.winner==='random'?Math.floor(crypto.getRandomValues(new Uint32Array(1))[0]/4294967296*config.prizes.length):Math.max(0,config.prizes.findIndex(p=>p.id===config.settings.winner));startIndex=index;endIndex=targetIndex(index,config.prizes.length,winner);startTime=performance.now();spinning=true;$('#spin').disabled=true;$('#spin-status').textContent='Лента вращается…';tell('spinning');}
function bind(){$('#spin-form')?.addEventListener('submit',e=>{e.preventDefault();spin();});$('#claim')?.addEventListener('click',()=>{screen='success';render();$('.content h1')?.focus({preventScroll:true});});$('#again')?.addEventListener('click',()=>{screen='start';render();});$('#copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(config.prizes[winner].code);$('#copy-status').textContent='Тестовый промокод скопирован';}catch{$('#copy-status').textContent='Выделите и скопируйте код вручную';const range=document.createRange();range.selectNodeContents($('#promo'));getSelection().removeAllRanges();getSelection().addRange(range);}});}
addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||e.data?.source!=='luck-studio')return;if(e.data.type==='config'){try{config=validate(e.data.config);device=e.data.device;winner=Math.max(0,Math.min(winner,config.prizes.length-1));render();}catch{}}if(e.data.type==='screen'){screen=['start','win','success'].includes(e.data.screen)?e.data.screen:'start';winner=config.settings.winner==='random'?Math.min(2,config.prizes.length-1):Math.max(0,config.prizes.findIndex(p=>p.id===config.settings.winner));render();}});addEventListener('resize',()=>render());
async function load(){try{if(parent===window){const req=indexedDB.open('luck-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');await new Promise(resolve=>{req.onsuccess=()=>{const q=req.result.transaction('projects').objectStore('projects').get('current');q.onsuccess=()=>{if(q.result)config=validate(q.result);req.result.close();resolve();};q.onerror=resolve;};req.onerror=resolve;});}}catch{}render();tell('ready');}load();
})();
